  function normalizeObject(root,targetMax){root.updateMatrixWorld(true);let box=new THREE.Box3().setFromObject(root),size=box.getSize(new THREE.Vector3()),center=box.getCenter(new THREE.Vector3());const s=targetMax/Math.max(size.x,size.y,size.z);root.scale.multiplyScalar(s);root.updateMatrixWorld(true);box=new THREE.Box3().setFromObject(root);center=box.getCenter(new THREE.Vector3());root.position.x-=center.x;root.position.z-=center.z;root.position.y-=box.min.y;root.updateMatrixWorld(true);return new THREE.Box3().setFromObject(root)}

