  function trackTargetName(name=''){const dot=name.lastIndexOf('.');let t=dot>=0?name.slice(0,dot):name;const slash=t.lastIndexOf('/');return slash>=0?t.slice(slash+1):t}
  function isolateTemplates(gltf,roots,kind){const templates=[];for(let i=0;i<roots.length;i++){const full=cloneSkeleton(gltf.scene),all=[];full.traverse(o=>{if(roots.some(n=>o.name===n))all.push(o)});const selected=full.getObjectByName(roots[i]);if(!selected)continue;all.forEach(o=>{if(o!==selected)o.parent?.remove(o)});selected.position.set(0,0,0);const names=new Set();selected.traverse(o=>{if(o.name)names.add(o.name)});const clips=(gltf.animations||[]).map((clip,j)=>{const tracks=clip.tracks.filter(tr=>{const target=trackTargetName(tr.name);if(!names.has(target))return false;if(target===selected.name&&/\.position$/i.test(tr.name))return false;return true}).map(tr=>tr.clone());return tracks.length?new THREE.AnimationClip(`${kind}_walk_${j}`,clip.duration,tracks):null}).filter(Boolean);full.updateMatrixWorld(true);let box=new THREE.Box3().setFromObject(full),size=box.getSize(new THREE.Vector3());if(size.y>.05){const s=1.82/size.y;full.scale.multiplyScalar(s);full.updateMatrixWorld(true);box=new THREE.Box3().setFromObject(full)}const wrap=new THREE.Group();wrap.add(full);full.position.y-=box.min.y;cleanScene(wrap,true);templates.push({scene:wrap,animations:clips,kind,name:roots[i]})}return templates}
