  function cleanView(root){root.traverse(o=>{if(o.isMesh){o.frustumCulled=false;o.renderOrder=12;o.castShadow=false;o.receiveShadow=false;if(o.material){const a=Array.isArray(o.material)?o.material:[o.material];const c=a.map(m=>{const n=m.clone();n.depthTest=false;n.depthWrite=false;return n});o.material=Array.isArray(o.material)?c:c[0]}}})}
  function setupImportedWeapons(){if(templates.rifle){try{const old=shotgunView,cand=new THREE.Group(),r=cloneSkeleton(templates.rifle.scene);cleanView(r);const box=new THREE.Box3().setFromObject(r),size=box.getSize(tmp),c=box.getCenter(tmp2),s=1.17/Math.max(size.x,size.y,size.z);r.scale.setScalar(s);r.position.set(-c.x*s,-c.y*s,-c.z*s);const wrap=new THREE.Group();wrap.rotation.y=Math.PI/2;wrap.position.set(0,.02,-.14);wrap.add(r);cand.add(wrap);const skin=viewMat({color:0x76523f,roughness:.85});for(const q of [[.21,-.27,-.02],[-.15,-.3,-.45]]){const arm=new THREE.Mesh(new THREE.CapsuleGeometry(.06,.42,5,8),skin);arm.position.set(...q);arm.rotation.x=-1.13;cand.add(arm)}cand.userData.muzzle=new THREE.PointLight(0xffad55,0,8,2);cand.userData.muzzle.position.set(0,.04,-1.05);cand.add(cand.userData.muzzle);old.removeFromParent();shotgunView=cand;weaponRoot.add(cand)}catch(e){console.warn(e)}}if(templates.hatchet){try{const old=hatchetView,cand=new THREE.Group(),h=cloneSkeleton(templates.hatchet.scene);cleanView(h);const box=new THREE.Box3().setFromObject(h),size=box.getSize(tmp),c=box.getCenter(tmp2),s=.92/Math.max(size.x,size.y,size.z);h.scale.setScalar(s);h.position.set(-c.x*s,-c.y*s,-c.z*s);cand.position.set(.12,-.03,-.1);cand.rotation.set(-.16,.08,-.72);cand.add(h);old.removeFromParent();hatchetView=cand;weaponRoot.add(cand)}catch(e){console.warn(e)}}}
  function applyWeapon(){shotgunView.visible=state.weapon==='shotgun';hatchetView.visible=state.weapon==='hatchet';updateHUD()}
  function setViewVisible(v){weaponRoot.visible=v;bodyRoot.visible=v}

  function spawnZombieAt(pos,index=0,fresh=false,wave=false){const pool=fresh&&templates.fresh.length?templates.fresh:templates.old.length?templates.old:templates.fresh;const tpl=pool[index%Math.max(1,pool.length)];let model;if(tpl)model=cloneSkeleton(tpl.scene);else{model=new THREE.Group();const mat=new THREE.MeshStandardMaterial({color:fresh?0x6b4c46:0x60675e,roughness:.9});const torso=new THREE.Mesh(new THREE.CapsuleGeometry(.3,.8,6,10),mat);torso.position.y=1.1;model.add(torso);const head=new THREE.Mesh(new THREE.SphereGeometry(.24,12,10),mat);head.position.y=1.78;model.add(head)}model.position.copy(pos);model.rotation.y=Math.random()*Math.PI*2;scene.add(model);const z={model,fresh,hp:fresh?190+Math.random()*90:95+Math.random()*35,maxHp:0,speed:fresh?1.65+Math.random()*.5:1.05+Math.random()*.35,damage:fresh?12+Math.floor(Math.random()*5):7+Math.floor(Math.random()*4),alive:true,alerted:wave,state:wave?'chase':'idle',lastAttack:0,nextGroan:performance.now()+800+Math.random()*2600,deathTime:0,coinDropped:false,mixer:null,action:null,wave};z.maxHp=z.hp;const idx=zombies.length;model.traverse(o=>{if(o.isMesh){o.userData.zombieIndex=idx;o.castShadow=true;o.receiveShadow=true}});if(tpl?.animations?.length){z.mixer=new THREE.AnimationMixer(model);z.action=z.mixer.clipAction(tpl.animations[0]);z.action.play();z.action.timeScale=fresh?1.18:.9;mixers.push(z.mixer)}zombies.push(z);return z}
  function spawnInitial(){const candidates=walkPoints.filter(p=>p.distanceTo(player.position)>8);for(let i=0;i<10;i++){const p=(candidates[(i*7+3)%Math.max(1,candidates.length)]||objectivePoints[(i+1)%objectivePoints.length]).clone();spawnZombieAt(p,i,i%3===0,false)}}
  function spawnWave(){const around=walkPoints.filter(p=>p.distanceTo(player.position)>6&&p.distanceTo(player.position)<24);for(let i=0;i<12;i++){const p=(around[(i*5+2)%Math.max(1,around.length)]||objectivePoints[(i+2)%objectivePoints.length]).clone();spawnZombieAt(p,i,true,true)}showSubtitle('system','sub4',4000);audio.objective()}

  function floorAt(x,z,currentY){raycaster.set(new THREE.Vector3(x,currentY+1.3,z),new THREE.Vector3(0,-1,0));raycaster.far=3.2;const hits=raycaster.intersectObjects(hospitalMeshes,false);for(const h of hits){if(!h.face)continue;const n=h.face.normal.clone().transformDirection(h.object.matrixWorld);if(n.y>.62)return h.point.y+.03}return currentY}
  function blocked(pos,dir,dist=.68){raycaster.set(pos.clone().add(new THREE.Vector3(0,1.0,0)),dir);raycaster.far=dist;return !!raycaster.intersectObjects(hospitalMeshes,false)[0]}
